def transform(grid):
    H=len(grid); W=len(grid[0])
    colors=sorted({v for row in grid for v in row if v}-{0})
    # find the two shapes' bboxes
    bboxes={}
    for c in colors:
        cells=[(i,j) for i in range(H) for j in range(W) if grid[i][j]==c]
        rs=[i for i,_ in cells]; cs=[j for _,j in cells]
        bboxes[c]=(min(rs),min(cs),max(rs),max(cs))
    a=min(colors,key=lambda c:bboxes[c][0])   # topmost shape gets mirrored
    b=[c for c in colors if c!=a][0]
    r0,c0,r1,c1=bboxes[a]
    out=[row[:] for row in grid]
    for i in range(H):
        for j in range(W):
            if grid[i][j]==b: out[i][j]=0
    for i in range(r0,r1+1):
        for j in range(W):
            if grid[i][j]==a:
                out[2*r1+1-i][j]=a
    return out

